// The archive wire (ticket #126): the Local copy's Shared tables against archive migration 130's column list
// (test/fixtures/migration-130-columns.json, generated by test/helpers/migrationColumns.ts), one full row per Shared
// table round-tripping through applyShared, `replace_whole`, `archive_ids` and the schema gate, and the typed RPC
// surface of src/shared/archiveWire.ts (function names, ops, the error map).
import { describe, expect, test } from "bun:test";
import { join } from "node:path";
import { openDb, type Db } from "../src/server/db";
import { applyShared, sqlValue } from "../src/server/localCopy/apply";
import { SHARED_SCHEMA } from "../src/server/localCopy/meta";
import {
  ARCHIVE_FUNCTIONS, ARCHIVE_SHARED_SCHEMA, editBelongsTo, ERROR_CODES, EVENT_TYPES, OPS, readArchiveError, REPLACE_WHOLE, SHARED_TABLES,
  WRITE_FUNCTIONS, wireWord, type WriteArgs,
} from "../src/shared/archiveWire";
import type { SharedTables, SharedTombstoneRow } from "../src/shared/sharedRows";
import cols130 from "./fixtures/migration-130-columns.json";
import { extractCreateTableColumns } from "./helpers/migrationColumns";
import { archiveChanges, loadArchiveFixture } from "./helpers/archive";
import { U } from "./helpers/seed";

const open = () => openDb(":memory:", join(import.meta.dir, "..", "migrations"));
const T = (n: number) => `2026-10-${String(n).padStart(2, "0")}T00:00:00.000000+00:00`;

/** The 130 tables the Local copy holds: all but the console-only grant table. */
const HELD = Object.keys(cols130).filter((t) => t !== "video_access");
/** Columns the Local copy keeps that the archive does not have (sharing-spec §6.1). */
const LOCAL_ONLY: Record<string, string[]> = { video_chapters: ["title_latin_source"] };
/** How a Postgres type of 130 is declared in the Local copy. */
const AFFINITY: Record<string, string> = {
  uuid: "TEXT", text: "TEXT", timestamptz: "TEXT", jsonb: "TEXT", boolean: "INTEGER", smallint: "INTEGER", integer: "INTEGER", "double precision": "REAL",
};

const localColumns = (db: Db, t: string) => db.query(`PRAGMA table_info(${t})`).all() as { name: string; type: string }[];

describe("the Local copy against migration 130", () => {
  test("the fixture is what the extractor reads from 130's layout", () => {
    const sql = `create table public.x (\n  id uuid primary key default gen_random_uuid(),\n  n double precision not null check (n >= 0),\n  constraint x_k unique (id, n),\n  constraint x_f foreign key (id)\n    references public.y (id) on delete cascade,\n  c text check (c in (\n    'a', 'b'))\n);`;
    expect(extractCreateTableColumns(sql)).toEqual({
      x: [{ name: "id", type: "uuid", notNull: true }, { name: "n", type: "double precision", notNull: true }, { name: "c", type: "text", notNull: false }],
    });
    expect(HELD.sort()).toEqual([
      "shared_tombstone", "video_artist_rejections", "video_artists", "video_chapter_rejections", "video_chapters", "video_edit_history",
      "video_exposed_songs", "video_proposed_artists", "video_proposed_songs", "video_proposed_versions", "videos",
    ]);
  });

  test("every Shared table has 130's columns, by name and affinity, plus only the documented Local-only ones", () => {
    const db = open();
    for (const t of HELD) {
      const want = (cols130 as Record<string, { name: string; type: string }[]>)[t]!;
      const have = localColumns(db, t);
      expect({ t, cols: have.map((c) => c.name).filter((c) => !(LOCAL_ONLY[t] ?? []).includes(c)).sort() }).toEqual({ t, cols: want.map((c) => c.name).sort() });
      for (const w of want) {
        const h = have.find((c) => c.name === w.name)!;
        expect({ t, c: w.name, type: h.type }).toEqual({ t, c: w.name, type: AFFINITY[w.type] ?? `?${w.type}` });
      }
    }
  });

  test("the shared schema stays 1: 130 is the first live shape", () => {
    expect(SHARED_SCHEMA).toBe(ARCHIVE_SHARED_SCHEMA);
  });
});

// One full row per Shared table, every column of 130 set.
const V1 = U(1001);
const PS = U(1002);
const PV = U(1003);
const PA = U(1004);
const ROWS: Required<Pick<SharedTables,
  "videos" | "video_chapters" | "video_artists" | "video_chapter_rejections" | "video_artist_rejections" | "video_proposed_songs" |
  "video_proposed_versions" | "video_proposed_artists" | "video_exposed_songs" | "video_edit_history">> = {
  video_proposed_songs: [{ id: PS, name: "zz-test Proposed", english_name: "Proposed", alternate_titles: "Alt", notes: "n", created_by: U(1), created_at: T(1), updated_at: T(2) }],
  video_proposed_versions: [{
    id: PV, song_id: null, proposed_song_id: PS, label: "Short", lyrics_cyrillic: "<p>а</p>", lyrics_transliteration: "<p>a</p>", lyrics_translation: "<p>t</p>",
    source: "booklet", footnotes_cyrillic: [{ id: 1, text: "f" }], footnotes_transliteration: [], footnotes_translation: [], created_by: U(1), created_at: T(1), updated_at: T(2),
  }],
  video_proposed_artists: [{ id: PA, name: "zz-test Artist", created_by: U(1), created_at: T(1), updated_at: T(2) }],
  video_exposed_songs: [{ id: U(1005), song_id: U(2001), artist_id: null, exposed_by: U(1), exposed_at: T(1), updated_at: T(2) }],
  videos: [{
    id: V1, youtube_id: "aaaaaaaaaaa", content_hash: "h1", instagram_id: "insta", rutube_id: "a555f5d081a84ab8bdb2e97107f82d2d", title: "Title", title_latin: "Title",
    title_latin_source: "manual", type: "song", type_suggested: true, song_id: null, proposed_song_id: PS, version_id: null, proposed_version_id: PV,
    song_suggested: true, suggestion_source: "title", poster_path: `${V1}/abcdef12.webp`, deleted_at: null, deleted_by: null, delete_reason: null,
    created_at: T(1), updated_at: T(3),
  }],
  video_chapters: [{
    id: U(1006), video_id: V1, start_s: 12.5, title: "Chapter", title_latin: "Chapter", song_id: U(2001), proposed_song_id: null, version_id: U(2002),
    proposed_version_id: null, suggested: true, source: "comment", created_at: T(1), updated_at: T(3),
  }],
  video_artists: [{ id: U(1007), video_id: V1, artist_id: null, proposed_artist_id: PA, position: 0, suggested: true, created_at: T(1), updated_at: T(3) }],
  video_chapter_rejections: [{ id: U(1008), video_id: V1, source: "description", start_s: 30.25, created_by: U(1), created_at: T(1), updated_at: T(3) }],
  video_artist_rejections: [{ id: U(1009), video_id: V1, artist_id: U(2003), proposed_artist_id: null, created_by: U(1), created_at: T(1), updated_at: T(3) }],
  video_edit_history: [{
    id: U(1010), video_id: V1, target_type: "video", target_id: V1, editor_id: U(1), event_type: "video.scanned", field_name: "title",
    old_value: null, new_value: { title: "Title" }, description: "scanned", reverses: null, created_at: T(3), updated_at: T(3),
  }, {
    id: U(1011), video_id: null, target_type: "proposed_song", target_id: PS, editor_id: U(1), event_type: "proposed.song_created", field_name: null,
    old_value: null, new_value: { name: "zz-test Proposed" }, description: "created", reverses: U(1010), created_at: T(3), updated_at: T(3),
  }],
};
const TOMBSTONE: SharedTombstoneRow = { id: U(1012), table_name: "video_proposed_artists", row_id: U(1013), kind: "deleted", replaced_by: null, at: T(4) };

describe("row types round-trip through applyShared", () => {
  test("each typed row carries exactly 130's columns", () => {
    for (const [t, rows] of Object.entries({ ...ROWS, shared_tombstone: [TOMBSTONE] })) {
      const want = (cols130 as Record<string, { name: string }[]>)[t]!.map((c) => c.name).sort();
      for (const r of rows) expect({ t, keys: Object.keys(r).sort() }).toEqual({ t, keys: want });
    }
  });

  test("every column of every row lands as written (booleans 0/1, jsonb as JSON text), in the shared_changes_since shape", () => {
    const db = open();
    const r = applyShared(db, {
      shared_schema: 1, server_time: T(5), since: null, watermark: T(4), tables: ROWS, replace_whole: ["video_exposed_songs"], tombstones: [TOMBSTONE],
    });
    expect(r.watermark).toBe(T(4)); // the server's
    expect(r.tombstones).toBe(1);
    for (const [t, rows] of Object.entries(ROWS)) {
      expect(r.applied[t]).toBe(rows.length);
      for (const row of rows as unknown as Record<string, unknown>[]) {
        const held = db.query(`SELECT * FROM ${t} WHERE id = ?`).get(row.id as string) as Record<string, unknown>;
        const want = Object.fromEntries(Object.entries(row).map(([k, v]) => [k, sqlValue(v)]));
        const got = Object.fromEntries(Object.keys(row).map((k) => [k, held[k]]));
        expect({ t, got }).toEqual({ t, got: want });
      }
    }
    expect(db.query("SELECT * FROM shared_tombstone").all()).toEqual([{ ...TOMBSTONE }]);
    // a write function's return ({tables, tombstones}) applies the same way; equal stamps are skipped
    const again = applyShared(db, { tables: ROWS, tombstones: [] });
    expect(again.applied).toEqual({});
    expect(again.skipped.videos).toBe(1);
  });

  test("a batch of another Shared schema is refused whole", () => {
    const db = open();
    expect(() => applyShared(db, { shared_schema: 2, tables: ROWS })).toThrow(/schema 2/);
    expect(db.query("SELECT COUNT(*) n FROM videos").get()).toEqual({ n: 0 });
    expect(() => applyShared(db, { replace_whole: ["videos" as any], tables: {} })).toThrow(/unknown table/);
  });
});

describe("replace_whole and archive_ids", () => {
  test("the exposure list and the track tables are replaced wholesale; an unchanged whole table rebuilds nothing", () => {
    const db = open();
    loadArchiveFixture(db);
    const a = archiveChanges();
    const n = (sql: string) => (db.query(sql).get() as { n: number }).n;
    const tracks = n("SELECT COUNT(*) n FROM archive_track");
    expect(tracks).toBeGreaterThan(1);
    // the same whole tables again: nothing changed, no rebuild
    const same = applyShared(db, { tables: { album_tracks: a.album_tracks, album_track_artists: a.album_track_artists, album_artists: a.album_artists }, replace_whole: [...REPLACE_WHOLE] });
    expect(same.reindex).toBe("none");
    expect(same.removed).toBe(n("SELECT COUNT(*) n FROM archive_track_artist") + n("SELECT COUNT(*) n FROM archive_album_credit")); // replaced per group, rewritten
    // one Track gone from the whole list: it leaves, with its Artists
    const gone = a.album_tracks![0]!;
    const fewer = applyShared(db, {
      tables: { album_tracks: a.album_tracks!.slice(1), album_track_artists: a.album_track_artists!.filter((x) => x.album_track_id !== gone.id) },
      replace_whole: ["album_tracks", "album_track_artists"],
    });
    expect(fewer.reindex).toBe("rebuild");
    expect(n("SELECT COUNT(*) n FROM archive_track")).toBe(tracks - 1);
    expect(db.query("SELECT COUNT(*) n FROM archive_track_artist WHERE track_id = ?").get(gone.id as string)).toEqual({ n: 0 });
    // the exposure list: a row the whole list lacks goes; not named in replace_whole, a missing table is left alone
    applyShared(db, { tables: { video_exposed_songs: ROWS.video_exposed_songs }, replace_whole: ["video_exposed_songs"] });
    const other = { id: U(1020), song_id: null, artist_id: U(2003), exposed_by: null, exposed_at: T(6), updated_at: T(6) };
    applyShared(db, { tables: { video_exposed_songs: [other] }, replace_whole: ["video_exposed_songs"] });
    expect(db.query("SELECT id FROM video_exposed_songs").all()).toEqual([{ id: U(1020) }]);
    applyShared(db, { tables: {}, replace_whole: ["video_exposed_songs"] });
    expect(n("SELECT COUNT(*) n FROM video_exposed_songs")).toBe(1);
  });

  test("archive_ids: held archive rows the caller can no longer read leave the Local copy and the index", () => {
    const db = open();
    loadArchiveFixture(db);
    const songs = (db.query("SELECT id FROM archive_song ORDER BY id").all() as { id: string }[]).map((s) => s.id);
    const versions = (db.query("SELECT id FROM archive_version ORDER BY id").all() as { id: string }[]).map((s) => s.id);
    const dropped = songs[0]!;
    expect(db.query("SELECT COUNT(*) n FROM search WHERE kind = 'song' AND ref_id = ?").get(dropped)).toEqual({ n: 1 });
    const r = applyShared(db, { tables: {}, archive_ids: { songs: songs.slice(1), song_lyrics: versions } });
    expect(r.removed).toBe(1);
    expect(db.query("SELECT COUNT(*) n FROM archive_song WHERE id = ?").get(dropped)).toEqual({ n: 0 });
    expect(db.query("SELECT COUNT(*) n FROM search WHERE kind = 'song' AND ref_id = ?").get(dropped)).toEqual({ n: 0 });
    expect(db.query("SELECT COUNT(*) n FROM archive_version").get()).toEqual({ n: versions.length }); // a list given whole keeps all
    expect(() => applyShared(db, { archive_ids: { videos: [] } as any })).toThrow(/unknown table/);
  });
});

describe("archiveWire", () => {
  test("13 functions: ten writers with their ops, three reads", () => {
    expect(ARCHIVE_FUNCTIONS).toHaveLength(13);
    expect(WRITE_FUNCTIONS).toHaveLength(10);
    expect(Object.keys(OPS).sort()).toEqual([...WRITE_FUNCTIONS].sort());
    expect(OPS.write_video_chapters).toEqual(["add", "update", "delete", "confirm", "confirm_all", "reject", "unreject"]);
    expect(OPS.elevate_version).toEqual(["elevate"]);
    expect(SHARED_TABLES).toHaveLength(18);
    expect(new Set(EVENT_TYPES).size).toBe(EVENT_TYPES.length);
    expect(editBelongsTo("write_video_artists", { event_type: "artist_link.repointed" })).toBe(true);
    expect(editBelongsTo("write_video_artists", { event_type: "video.title_changed" })).toBe(false);
    expect(editBelongsTo("elevate_song", { event_type: "proposed.song_elevated" })).toBe(false);
    // the args type checks a payload against its op
    const args: WriteArgs<"write_videos", "delete"> = { p_op: "delete", p_target: U(1), p_payload: { reason: "duplicate" }, p_expected_updated_at: T(1), p_edits: [{ event_type: "video.deleted", description: "deleted" }] };
    expect(args.p_payload.reason).toBe("duplicate");
  });

  test("the error map: SQLSTATE -> wire word, DETAIL parsed", () => {
    expect(ERROR_CODES).toEqual({ "42501": "forbidden", P0002: "not-found", VD409: "conflict", VD422: "duplicate-candidate", VD423: "in-use", "23505": "exists", "22023": "malformed" });
    expect(wireWord("42501")).toBe("forbidden");
    expect(wireWord("PGRST301")).toBeNull();
    expect(wireWord("toString")).toBeNull();
    const conflict = { table: "videos", id: U(1), updated_at: T(2), last_edit: null };
    expect(readArchiveError({ code: "VD409", message: "conflict", details: JSON.stringify(conflict), hint: "conflict" })).toEqual({ word: "conflict", code: "VD409", message: "conflict", detail: conflict });
    const cands = [{ kind: "archive" as const, id: U(2), name: "Alash" }];
    expect(readArchiveError({ code: "VD422", message: "dup", details: JSON.stringify(cands) }).detail).toEqual(cands);
    expect(readArchiveError({ code: "VD422", message: "dup", details: "not json" }).detail).toEqual([]);
    expect(readArchiveError({ code: "VD423", message: "in use", details: '{"count":3}' }).detail).toEqual({ count: 3 });
    expect(readArchiveError({ code: "P0002", message: "gone" })).toEqual({ word: "not-found", code: "P0002", message: "gone", detail: null });
    expect(readArchiveError({ code: null, message: "x", hint: "forbidden" })).toMatchObject({ word: "forbidden", code: "42501" });
    expect(readArchiveError({ code: "PGRST301", message: "jwt" })).toEqual({ word: "unknown", code: "PGRST301", message: "jwt", detail: null });
  });
});
